'use strict';

// —— Boot loader: hide only after menu is fully ready (no early flash / hover freeze) ——
(function initBootLoader() {
  const markReady = () => {
    try {
      if (typeof window.__markMenuReady === 'function') {
        window.__markMenuReady();
        return;
      }
    } catch (_) {}
    try {
      if (typeof window.__hideBootLoader === 'function') {
        window.__hideBootLoader();
        return;
      }
    } catch (_) {}
    const el = document.getElementById('bootLoader');
    if (!el || el.classList.contains('hide')) return;
    el.classList.add('hide');
    el.setAttribute('data-hidden', '1');
    try { document.body.classList.remove('bp-booting'); document.body.classList.add('bp-menu-ready', 'bp-menu-warm'); } catch (_) {}
    setTimeout(() => { try { el.remove(); } catch (_) {} }, 600);
  };
  try {
    const t0 = performance.now();
    // Minimum time so the animated boot screen is visible; then wait for idle + paint
    const MIN_MS = 700;
    const finish = () => {
      const left = Math.max(0, MIN_MS - (performance.now() - t0));
      const reveal = () => {
        // Prefer idle callback so heavy first-paint work is done before menu is interactive
        const go = () => markReady();
        try {
          if (typeof requestIdleCallback === 'function') {
            requestIdleCallback(go, { timeout: 900 });
          } else {
            setTimeout(go, 40);
          }
        } catch (_) {
          setTimeout(go, 40);
        }
      };
      setTimeout(reveal, left);
    };
    if (document.readyState === 'complete') finish();
    else window.addEventListener('load', finish, { once: true });
    // Absolute cap — never leave user stuck on loader
    setTimeout(markReady, 4500);
  } catch (_) {
    setTimeout(markReady, 500);
  }
})();

// —— Match intro (classic / versus) ——
let matchIntroTimer = null;
function showMatchIntro(opts) {
  opts = opts || {};
  return new Promise((resolve) => {
    try {
      if (settings && settings.matchIntro === '0') { resolve(); return; }
    } catch (_) {}
    if (opts.skip) { resolve(); return; }
    const el = document.getElementById('matchIntro');
    if (!el) { resolve(); return; }
    // Already showing — wait for it, do not stack
    if (el.classList.contains('visible') && matchIntroTimer) {
      const wait = setInterval(() => {
        if (!el.classList.contains('visible')) {
          clearInterval(wait);
          resolve();
        }
      }, 50);
      setTimeout(() => { clearInterval(wait); resolve(); }, 2800);
      return;
    }
    // Reduced motion: still show a short static flash (do not skip entirely)
    let reduced = false;
    try {
      reduced = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
    } catch (_) {}
    const label = document.getElementById('miLabel');
    const title = document.getElementById('miTitle');
    const sub = document.getElementById('miSub');
    if (label) label.textContent = opts.label || (typeof globalThis.t==='function'?globalThis.t('js.loading','Загрузка'):'Загрузка');
    if (title) title.textContent = opts.title || (typeof globalThis.t==='function'?globalThis.t('js.almostReady','Почти готово…'):'Почти готово…');
    if (sub) sub.textContent = opts.sub || '';
    el.classList.remove('mi-go');
    el.classList.add('visible');
    el.setAttribute('aria-hidden', 'false');
    // Force visible — hideMatchLoading leaves inline display:none which overrides .visible
    try {
      el.style.display = 'flex';
      el.style.pointerEvents = 'auto';
      el.style.opacity = '1';
      el.style.visibility = 'visible';
      el.style.zIndex = '9000';
    } catch (_) {}
    if (matchIntroTimer) clearTimeout(matchIntroTimer);
    const hideIntro = () => {
      try {
        el.classList.remove('visible', 'mi-go');
        el.setAttribute('aria-hidden', 'true');
        el.style.display = 'none';
        el.style.pointerEvents = 'none';
      } catch (_) {}
      matchIntroTimer = null;
      resolve();
    };
    // Respect explicit ms. Default 1200. goPhase = final «Старт!» flash
    const requested = (typeof opts.ms === 'number') ? opts.ms : 1200;
    const total = reduced
      ? Math.min(600, Math.max(200, requested))
      : Math.min(2200, Math.max(0, requested));
    const goPhase = total <= 0 ? 0 : Math.min(520, Math.max(280, Math.floor(total * 0.35)));
    const hold = Math.max(0, total - goPhase);
    if (total <= 0) {
      hideIntro();
      return;
    }
    matchIntroTimer = setTimeout(() => {
      el.classList.add('mi-go');
      if (label) label.textContent = (typeof globalThis.t==='function'?globalThis.t('js.ready','Готово'):'Готово');
      if (title) title.textContent = opts.goText || (typeof globalThis.t==='function'?globalThis.t('js.start','Старт!'):'Старт!');
      if (sub) sub.textContent = opts.sub || '';
      matchIntroTimer = setTimeout(hideIntro, goPhase);
    }, hold);
  });
}

